#!/usr/bin/env python3
"""
Structural leverage scorer — 5 architectural leverage types beyond Naval's 4 operational types.

Naval's leverage.py: code, media, capital, labor (operational — HOW you produce)
This module: entity, trust, info_asymmetry, timing, regulatory (structural — HOW you architect)

Usage:
    python -m money_mechanisms.structural_leverage --description "franchise model with IP licensing and real estate"
"""

import argparse
import json
import re
import sys
from typing import Dict, List, Tuple


class StructuralLeverageScorer:
    """Scorer for architectural leverage types."""

    STRUCTURAL_TYPES = {
        "entity_leverage": {
