#!/usr/bin/env python3
"""Tests for dual-axis capital-path-classifier."""
import json
import subprocess
import sys
from pathlib import Path

CLASSIFIER_PATH = str(
    Path(__file__).resolve().parents[1] / "capital-path-classifier.py"
)


def run_classifier(profile: dict) -> dict:
    result = subprocess.run(
        [sys.executable, CLASSIFIER_PATH, "--profile-json", json.dumps(profile)],
        capture_output=True,
        text=True,
    )
    assert result.returncode == 0, f"Classifier failed: {result.stderr}"
    return json.loads(result.stdout)


def test_developer_routes_to_leverage_sprint():
    profile = {
        "capital_usd": 500,
        "skills": {"primary": ["software_development", "ai_ml", "automation"]},
        "advantages": {"technical_skills": {"enabled": True, "years": 15}},
        "existing_assets": {
            "email_list": 0,
            "social_following": 0,
            "physical_networks": ["VN tech community"],
            "relationship_capital": ["coffee farmers"],
        },
    }
    result = run_classifier(profile)
    assert result["track"] == "LEVERAGE_SPRINT", f"Got {result['track']}"
    assert result["leverage_access_score"] >= 7


def test_domain_expert_routes_to_leverage_entry():
    profile = {
        "capital_usd": 300,
        "skills": {"primary": [], "secondary": ["commodity_trading", "sourcing"]},
        "advantages": {"geographic_position": {"enabled": True}},
        "existing_assets": {
            "email_list": 0,
            "social_following": 0,
            "physical_networks": ["Dak Lak coops"],
            "relationship_capital": ["farmers", "traders"],
        },
    }
    result = run_classifier(profile)
    assert result["track"] == "LEVERAGE_ENTRY", f"Got {result['track']}"
    assert 4 <= result["leverage_access_score"] <= 6


def test_zero_skill_routes_to_cashflow_seed():
    profile = {
        "capital_usd": 100,
        "skills": {"primary": [], "secondary": []},
        "existing_assets": {
            "email_list": 0,
            "social_following": 0,
            "physical_networks": [],
            "relationship_capital": [],
        },
    }
    result = run_classifier(profile)
    assert result["track"] == "CASHFLOW_SEED", f"Got {result['track']}"
    assert result["leverage_access_score"] <= 3


def test_tier1_unchanged():
    profile = {"capital_usd": 3000}
    result = run_classifier(profile)
    assert result["track"] == "HYBRID", f"Got {result['track']}"
    assert result["tier"] == "TIER_1"


def test_output_includes_leverage_fields():
    profile = {"capital_usd": 500, "skills": {"primary": ["software_development"]}}
    result = run_classifier(profile)
    assert "leverage_access_score" in result
    assert "leverage_dimensions" in result


def test_empty_profile_defaults():
    result = run_classifier({})
    assert result["tier"] == "TIER_0"
    assert result["track"] == "CASHFLOW_SEED"
    assert result["leverage_access_score"] == 0


def test_current_founder_profile():
    profile_path = (
        Path(__file__).resolve().parents[3] / "data" / "founder-profile.json"
    )
    if not profile_path.exists():
        return
    profile = json.loads(profile_path.read_text("utf-8"))
    result = run_classifier(profile)
    assert result["track"] == "LEVERAGE_SPRINT", f"Founder should be LEVERAGE_SPRINT, got {result['track']}"
    assert result["leverage_access_score"] >= 7


if __name__ == "__main__":
    tests = [
        test_developer_routes_to_leverage_sprint,
        test_domain_expert_routes_to_leverage_entry,
        test_zero_skill_routes_to_cashflow_seed,
        test_tier1_unchanged,
        test_output_includes_leverage_fields,
        test_empty_profile_defaults,
        test_current_founder_profile,
    ]
    passed = 0
    failed = 0
    for t in tests:
        try:
            t()
            print(f"  PASS: {t.__name__}")
            passed += 1
        except Exception as e:
            print(f"  FAIL: {t.__name__}: {e}")
            failed += 1
    print(f"\n{passed}/{passed + failed} tests passed")
    sys.exit(1 if failed else 0)

